{"file_path":"src/graph.js","content":"/** Ordering the task graph. */

/** A dependency cycle a depth-first search found, naming the tasks around it. */
export class CycleError extends Error {
  /** @param {string[]} cycle - the names from the re-entered task back to itself. */
  constructor(cycle) {
    super(`cycle: ${cycle.join(' -> ')}`)
    this.name = 'CycleError'
    this.cycle = cycle
  }
}

/**
 * The first cycle a depth-first search finds, starting from each task in
 * ascending name order and walking each task's dependencies in ascending
 * name order.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[]|null} the cycle, from the re-entered task back to itself, or null.
 */
function findCycle(tasks) {
  const state = new Map()
  const stack = []
  function visit(name) {
    if (state.get(name) === 'done') return null
    if (state.get(name) === 'visiting') return [...stack.slice(stack.indexOf(name)), name]
    state.set(name, 'visiting')
    stack.push(name)
    for (const dependency of [...tasks.get(name).needs].sort()) {
      const cycle = visit(dependency)
      if (cycle !== null) return cycle
    }
    stack.pop()
    state.set(name, 'done')
    return null
  }
  for (const name of [...tasks.keys()].sort()) {
    const cycle = visit(name)
    if (cycle !== null) return cycle
  }
  return null
}

/**
 * The tasks in run order: repeatedly the lexicographically smallest task whose
 * dependencies have all been emitted.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[]} the names in run order.
 * @throws {CycleError} when the dependencies contain a cycle.
 */
export function order(tasks) {
  const cycle = findCycle(tasks)
  if (cycle !== null) throw new CycleError(cycle)
  const remaining = new Set(tasks.keys())
  const emitted = new Set()
  const out = []
  while (remaining.size > 0) {
    const ready = [...remaining].filter(name => tasks.get(name).needs.every(need => emitted.has(need))).sort()
    remaining.delete(ready[0])
    emitted.add(ready[0])
    out.push(ready[0])
  }
  return out
}
"}

