import { readFileSync } from 'node:fs'
import { splitLines } from './parse.js'

const DIGEST = /^[0-9a-f]{8}$/

/** One refusal reading or parsing a snapshot, already worded as the specification wants it. */
export class SnapshotError extends Error {
  /** @param {string} message - the full message, without the `error: ` prefix. */
  constructor(message) {
    super(message)
    this.name = 'SnapshotError'
  }
}

/**
 * Parse a digest snapshot: a line per recorded path, trimmed, with an empty
 * line and a line starting with `#` ignored, and the rest split on runs of
 * whitespace into a path and its digest.
 * @param {string} path - the snapshot file's path.
 * @returns {Map<string, string>} the recorded digest by path.
 * @throws {SnapshotError} when the file cannot be read or a line is malformed.
 */
export function parseSnapshot(path) {
  let text
  try {
    text = readFileSync(path, 'utf8')
  } catch {
    throw new SnapshotError(`cannot read snapshot ${path}`)
  }
  const digests = new Map()
  for (const [index, raw] of splitLines(text).entries()) {
    const line = index + 1
    const text = raw.trim()
    if (text === '' || text.startsWith('#')) continue
    const words = text.split(/\s+/u)
    if (words.length !== 2) throw new SnapshotError(`${path}: line ${line}: expected <path> <digest>`)
    const [recordedPath, digest] = words
    if (!DIGEST.test(digest)) throw new SnapshotError(`${path}: line ${line}: invalid digest ${digest}`)
    if (digests.has(recordedPath)) throw new SnapshotError(`${path}: line ${line}: path ${recordedPath} is recorded twice`)
    digests.set(recordedPath, digest)
  }
  return digests
}
"}

